}

.product-icon svg {
  width: 32px;
  height: 32px;
  color: var(--white);
}

.product-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.product-card p {
  color: var(--gray-600);
  font-size: 0.9375rem;
}

@media (max-width: 1024px) {
  .products-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .products-grid {
    grid-template-columns: 1fr;
  }
}

/* Tabbed Features */
.features-tabs {
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}

.feature-tab {
  padding: 14px 28px;
  font-weight: 600;
  color: var(--gray-600);
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius);
  cursor: pointer;
  transition: all 0.2s ease;
}

.feature-tab:hover {
  border-color: var(--gray-300);
  color: var(--gray-800);
}

.feature-tab.active {
  background: var(--primary);
  border-color: var(--primary);
  color: var(--white);
}

.features-content {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 48px;
  box-shadow: var(--shadow-lg);
}

.feature-panel {
  display: none;
}

.feature-panel.active {
  display: block;
  animation: fadeIn 0.3s ease;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.feature-panel h3 {
  font-size: 1.75rem;
  margin-bottom: 16px;
}

.feature-panel > p {
  color: var(--gray-600);
  font-size: 1.125rem;
  margin-bottom: 32px;
}

.feature-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.feature-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
}

.feature-item-icon {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  background: rgba(37, 99, 235, 0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.feature-item-icon svg {
  width: 24px;
  height: 24px;
  color: var(--primary);
}

.feature-item h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.feature-item p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

@media (max-width: 768px) {
  .feature-list {
    grid-template-columns: 1fr;
  }
}

/* Integrations Grid */
.integrations-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.integration-item {
  background: var(--white);
  border-radius: var(--radius);
  padding: 24px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border: 1px solid var(--gray-200);
  transition: all 0.2s ease;
}

.integration-item:hover {
  border-color: var(--primary);
  box-shadow: var(--shadow);
}

.integration-logo {
  width: 48px;
  height: 48px;
  border-radius: 8px;
  background: var(--gray-100);
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  font-size: 0.875rem;
  color: var(--gray-600);
}

.integration-item span {
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--gray-600);
}

@media (max-width: 1024px) {
  .integrations-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (max-width: 640px) {
  .integrations-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Testimonials Carousel */
.testimonials-section {
  overflow: hidden;
}

.testimonials-carousel {
  position: relative;
  max-width: 1000px;
  margin: 0 auto;
}

.testimonials-track {
  display: flex;
  gap: 24px;
  transition: transform 0.4s ease;
}

.testimonial-card {
  flex: 0 0 calc(33.333% - 16px);
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-100);
}

.testimonial-quote {
  font-size: 0.9375rem;
  color: var(--gray-700);
  margin-bottom: 24px;
  line-height: 1.7;
}

.testimonial-author {
  display: flex;
  align-items: center;
  gap: 16px;
}

.testimonial-avatar {
  width: 56px;
  height: 56px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary) 0%, var(--accent) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--white);
  font-weight: 700;
  font-size: 1.25rem;
}

.testimonial-info h4 {
  font-size: 1rem;
  margin-bottom: 4px;
}

.testimonial-info p {
  font-size: 0.875rem;
  color: var(--gray-500);
}

.testimonial-badge {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: rgba(37, 99, 235, 0.08);
  border-radius: 100px;
  font-size: 0.75rem;
  font-weight: 600;
  color: var(--primary);
  margin-top: 16px;
}

.testimonials-controls {
  display: flex;
  justify-content: center;
  gap: 16px;
  margin-top: 40px;
}

.testimonials-btn {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--white);
  border: 2px solid var(--gray-200);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.2s ease;
}

.testimonials-btn:hover {
  border-color: var(--primary);
  background: var(--primary);
  color: var(--white);
}

.testimonials-btn svg {
  width: 20px;
  height: 20px;
}

@media (max-width: 1024px) {
  .testimonial-card {
    flex: 0 0 calc(50% - 12px);
  }
}

@media (max-width: 640px) {
  .testimonial-card {
    flex: 0 0 100%;
  }
}

/* FAQ Accordion */
.faq-list {
  max-width: 800px;
  margin: 0 auto;
}

.faq-item {
  border-bottom: 1px solid var(--gray-200);
}

.faq-question {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 24px 0;
  font-size: 1.125rem;
  font-weight: 600;
  color: var(--gray-800);
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: color 0.2s ease;
}

.faq-question:hover {
  color: var(--primary);
}

.faq-icon {
  width: 24px;
  height: 24px;
  transition: transform 0.3s ease;
}

.faq-item.active .faq-icon {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-item.active .faq-answer {
  max-height: 500px;
}

.faq-answer p {
  padding-bottom: 24px;
  color: var(--gray-600);
  line-height: 1.7;
}

/* Pricing Cards */
.pricing-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.pricing-card {
  background: var(--white);
  border-radius: var(--radius-xl);
  padding: 40px;
  border: 2px solid var(--gray-200);
  transition: all 0.3s ease;
}

.pricing-card:hover {
  border-color: var(--primary);
}

.pricing-card.featured {
  border-color: var(--primary);
  box-shadow: var(--shadow-xl);
  transform: scale(1.05);
  position: relative;
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -12px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--primary);
  color: var(--white);
  padding: 6px 20px;
  border-radius: 100px;
  font-size: 0.875rem;
  font-weight: 600;
}

.pricing-name {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.pricing-price {
  display: flex;
  align-items: baseline;
  gap: 4px;
  margin-bottom: 16px;
}

.pricing-price .amount {
  font-size: 3rem;
  font-weight: 800;
  color: var(--gray-900);
}

.pricing-price .period {
  color: var(--gray-500);
}

.pricing-description {
  color: var(--gray-600);
  margin-bottom: 24px;
  padding-bottom: 24px;
  border-bottom: 1px solid var(--gray-100);
}

.pricing-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 32px;
}

.pricing-features li {
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--gray-700);
}

.pricing-features li svg {
  width: 20px;
  height: 20px;
  color: var(--success);
  flex-shrink: 0;
}

.pricing-card .btn {
  width: 100%;
}

@media (max-width: 1024px) {
  .pricing-grid {
    grid-template-columns: 1fr;
    max-width: 400px;
    margin: 0 auto;
  }

  .pricing-card.featured {
    transform: none;
  }
}

/* CTA Banner */
.cta-banner {
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
  border-radius: var(--radius-xl);
  padding: 80px 60px;
  text-align: center;
  color: var(--white);
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 200%;
  background: radial-gradient(ellipse, rgba(255,255,255,0.1) 0%, transparent 70%);
  pointer-events: none;
}

.cta-banner h2 {
  color: var(--white);
  margin-bottom: 16px;
}

.cta-banner p {
  font-size: 1.25rem;
  opacity: 0.9;
  margin-bottom: 32px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.cta-banner .btn-accent {
  background: var(--accent);
}

.cta-banner .btn-secondary {
  background: transparent;
  border-color: rgba(255,255,255,0.3);
  color: var(--white);
}

.cta-banner .btn-secondary:hover {
  background: rgba(255,255,255,0.1);
  border-color: rgba(255,255,255,0.5);
}

/* Footer */
.footer {
  background: var(--gray-900);
  color: var(--white);
  padding: 80px 0 40px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 60px;
}

.footer-brand p {
  color: var(--gray-400);
  margin-top: 16px;
  max-width: 300px;
}

.footer-links h4 {
  color: var(--white);
  font-size: 1rem;
  margin-bottom: 20px;
}

.footer-links ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.footer-links a {
  color: var(--gray-400);
  transition: color 0.2s ease;
}

.footer-links a:hover {
  color: var(--white);
}

.footer-bottom {
  padding-top: 40px;
  border-top: 1px solid var(--gray-800);
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--gray-500);
  font-size: 0.875rem;
}

.footer-legal {
  display: flex;
  gap: 24px;
}

.footer-legal a {
  color: var(--gray-500);
  transition: color 0.2s ease;
}

.footer-legal a:hover {
  color: var(--white);
}

@media (max-width: 1024px) {
  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .footer-grid {
    grid-template-columns: 1fr;
  }

  .footer-bottom {
    flex-direction: column;
    gap: 16px;
    text-align: center;
  }
}

/* Feature Cards */
.feature-cards-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.feature-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-100);
  transition: all 0.3s ease;
}

.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.feature-card-icon {
  width: 64px;
  height: 64px;
  border-radius: var(--radius);
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 24px;
}

.feature-card-icon svg {
  width: 32px;
  height: 32px;
  color: var(--white);
}

.feature-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.feature-card p {
  color: var(--gray-600);
}

@media (max-width: 768px) {
  .feature-cards-grid {
    grid-template-columns: 1fr;
  }
}

/* Steps */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px;
}

.step-card {
  text-align: center;
  position: relative;
}

.step-number {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary) 0%, var(--primary-light) 100%);
  color: var(--white);
  font-size: 1.5rem;
  font-weight: 800;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.step-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.step-card p {
  color: var(--gray-600);
}

@media (max-width: 768px) {
  .steps-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}

/* Spotlight Cards */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.spotlight-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-100);
}

.spotlight-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.spotlight-card p {
  color: var(--gray-600);
}

@media (max-width: 768px) {
  .spotlight-grid {
    grid-template-columns: 1fr;
  }
}

/* Value Props */
.value-props-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
}

.value-prop-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-100);
  text-align: center;
  transition: all 0.3s ease;
}

.value-prop-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-xl);
}

.value-prop-icon {
  width: 80px;
  height: 80px;
  border-radius: 50%;
  background: linear-gradient(135deg, rgba(37, 99, 235, 0.1) 0%, rgba(249, 115, 22, 0.1) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 24px;
}

.value-prop-icon svg {
  width: 40px;
  height: 40px;
  color: var(--primary);
}

.value-prop-card h3 {
  font-size: 1.25rem;
  margin-bottom: 12px;
}

.value-prop-card p {
  color: var(--gray-600);
}

@media (max-width: 768px) {
  .value-props-grid {
    grid-template-columns: 1fr;
  }
}

/* File Types */
.file-types-grid {
  display: grid;
  grid-template-columns: repeat(6, 1fr);
  gap: 16px;
}

.file-type-item {
  background: var(--white);
  border-radius: var(--radius);
  padding: 24px 16px;
  text-align: center;
  border: 1px solid var(--gray-200);
  transition: all 0.2s ease;
}

.file-type-item:hover {
  border-color: var(--primary);
  transform: translateY(-2px);
}

.file-type-icon {
  width: 48px;
  height: 48px;
  margin: 0 auto 12px;
  background: var(--gray-100);
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.file-type-icon svg {
  width: 24px;
  height: 24px;
  color: var(--gray-600);
}

.file-type-item span {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--gray-700);
}

@media (max-width: 1024px) {
  .file-types-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

@media (max-width: 640px) {
  .file-types-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

/* Tools Grid */
.tools-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.tool-category {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  border: 1px solid var(--gray-200);
  transition: all 0.2s ease;
}

.tool-category:hover {
  border-color: var(--primary);
}

.tool-category h4 {
  font-size: 1rem;
  margin-bottom: 16px;
  color: var(--primary);
}

.tool-category ul {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.tool-category li {
  font-size: 0.9375rem;
  color: var(--gray-700);
}

@media (max-width: 1024px) {
  .tools-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 640px) {
  .tools-grid {
    grid-template-columns: 1fr;
  }
}

/* Resources Grid */
.resources-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.resource-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 32px;
  box-shadow: var(--shadow);
  border: 1px solid var(--gray-100);
  transition: all 0.3s ease;
}

.resource-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
}

.resource-card h3 {
  font-size: 1.125rem;
  margin-bottom: 12px;
}

.resource-card p {
  color: var(--gray-600);
  margin-bottom: 16px;
}

.resource-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--primary);
  font-weight: 600;
  transition: gap 0.2s ease;
}

.resource-link:hover {
  gap: 12px;
}

.resource-link svg {
  width: 20px;
  height: 20px;
}

@media (max-width: 768px) {
  .resources-grid {
    grid-template-columns: 1fr;
  }
}

/* Membership Stats */
.membership-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 32px;
  background: var(--gray-900);
  border-radius: var(--radius-xl);
  padding: 60px;
  color: var(--white);
}

.membership-stat {
  text-align: center;
}

.membership-stat-value {
  font-size: 3rem;
  font-weight: 800;
  background: linear-gradient(135deg, var(--primary-light) 0%, var(--accent) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  margin-bottom: 8px;
}

.membership-stat-label {
  color: var(--gray-400);
  font-weight: 500;
}

@media (max-width: 768px) {
  .membership-stats {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}

/* Animations */
@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}

.animate-float {
  animation: float 3s ease-in-out infinite;
}

/* Utilities */
.text-center { text-align: center; }
.mb-4 { margin-bottom: 16px; }
.mb-8 { margin-bottom: 32px; }
.mb-12 { margin-bottom: 48px; }
